namespace Elevant.Domain.Entities.Commercial;
/// <summary>Private metadata. The storage key is generated by the server and never returned by HTTP.</summary>
public sealed class FinancePayablesAttachment : Entity<long>
{
    public Guid PublicId { get; init; }
    public long? SupplierInvoiceId { get; init; }
    public long? ExpenseClaimId { get; init; }
    public string ObjectKey { get; init; } = string.Empty;
    public string ContentType { get; init; } = string.Empty;
    public long Length { get; init; }
    public string Sha256 { get; init; } = string.Empty;
    public long UploadedByAccountId { get; init; }
    public DateTimeOffset CreatedAt { get; init; }
}
